{
  "model": "Qwen3-TTS-12Hz-1.7B-Base",
  "input": {
    "text": "嗯",
    "language": "Chinese",
    "voice_setting": {
      "voice_id": "qwen3-profile-31493a68507e241f",
      "seed": 497160264,
      "voice_profile": "男性，听感三十多岁，音色明亮而有弹性，吐字清楚，语速偏快但层次分明，情绪起伏较容易从语气中听出来。",
      "reference_text": "我在安排本周六下午的亲友聚会，一共八个人，从一点半到六点。场地是小区活动室，走五分钟能到运河步道。大家对聊天、散步和桌游各有偏好，我想做一套能临场调整、又不把人弄得太累的流程。",
      "reference_directory": "/ytech_m2v8_hdd/workspace/kling_mm/zhengyuanhong/read_paper/全双工/duplex-env-scaling-package/project/duplex_v2/runs/20261109-v29-user-aside-hundred-service-recovery/branches/G02-N008-R01-V01/R01-V01/audio/voices/user-reference",
